import {
    Component,
    effect,
    inject,
    input,
    linkedSignal,
    model,
    OnInit,
    signal,
} from '@angular/core';

import { ScrollingModule } from '@angular/cdk/scrolling';
import { DatePipe } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatRippleModule } from '@angular/material/core';
import { OrganisationService, SettingsService } from '@placeos/common';
import { AsyncHandler } from 'libs/common/src/lib/async-handler.class';
import { HotkeysService } from 'libs/common/src/lib/hotkeys.service';
import {
    ClientEvent,
    RemoteLoggingService,
} from 'libs/common/src/lib/remote-logging.service';
import { CustomTooltipComponent } from './custom-tooltip.component';
import { IconComponent } from './icon.component';
import { JsonDisplayComponent } from './json-display.component';
import { TranslatePipe } from './translate.pipe';

const COLOR_MAP = {
    console: 'bg-success-light text-black',
    network: 'bg-success text-success-content',
    dom: 'bg-warning-light text-black',

    log: `bg-info-light text-black`,
    info: `bg-info text-info-content`,
    warn: `bg-warning text-warning-content`,
    debug: `bg-base-300 text-base-content`,
    error: `bg-error text-error-content`,
};

const URL_STARTS = [
    'tel:',
    'mailto:',
    'http:',
    'https:',
    'ftp:',
    'ws:',
    'wss:',
];

/** Lower case search text of each log entry, built once per entry */
const SEARCH_TEXT = new WeakMap<ClientEvent, string>();

/** Text of a log entry for the filter. Includes the contents of objects. */
function logSearchText(event: ClientEvent): string {
    let text = SEARCH_TEXT.get(event);
    if (text === undefined) {
        let data: string;
        try {
            // Errors have no enumerable fields, so use their message
            data =
                JSON.stringify(event.data, (_, value) =>
                    value instanceof Error ? `${value}` : value,
                ) ?? '';
        } catch {
            // Circular values cannot be JSON
            data = `${event.data}`;
        }
        text = `${event.type} ${event.subtype} ${data}`.toLowerCase();
        SEARCH_TEXT.set(event, text);
    }
    return text;
}

@Component({
    selector: `debug-console`,
    template: `
        @if (show()) {
            <div
                class="border-base-300 bg-base-200 text-base-content absolute bottom-2 left-2 z-998 flex h-96 max-h-[65vh] w-160 max-w-[80vw] flex-col overflow-hidden rounded-sm border shadow-sm"
            >
                <div
                    class="border-base-300 bg-base-100 flex items-center justify-between border-b"
                >
                    <div class="p-2">{{ 'COMMON.CONSOLE' | translate }}</div>
                    <button
                        [attr.aria-label]="'COMMON.CLOSE' | translate"
                        icon
                        matRipple
                        (click)="show.set(false)"
                    >
                        <icon>close</icon>
                    </button>
                </div>
                @if (filtered_logs()?.length) {
                    <cdk-virtual-scroll-viewport
                        itemSize="32"
                        class="h-120 max-h-full w-full flex-1"
                    >
                        <div
                            class="hover:bg-base-100 flex h-8 max-w-full items-center space-x-1 truncate p-2 font-mono text-xs"
                            *cdkVirtualFor="
                                let log of filtered_logs();
                                trackBy: trackByFn
                            "
                        >
                            <div
                                class="bg-base-100/10 rounded-sm p-1 font-mono text-[0.625rem] uppercase"
                            >
                                {{ log.timestamp | date: 'HH:mm:ss' }}
                            </div>
                            <!-- <div
                                [class]="
                                    'p-1 uppercase ' +
                                    colors[log.type] +
                                    ' rounded-sm font-mono'
                                "
                            >
                                {{ log.type }}
                            </div> -->
                            <div
                                [class]="
                                    'p-1 capitalize ' +
                                    colors[log.subtype] +
                                    ' w-16 rounded-sm text-center font-mono'
                                "
                            >
                                {{ log.subtype }}
                            </div>
                            @for (obj of log.data; track obj) {
                                <div
                                    class="pl-1 font-mono"
                                    [attr.data-type]="type(obj)"
                                >
                                    @switch (type(obj)) {
                                        @case ('link') {
                                            <a
                                                class="font-mono"
                                                [href]="obj"
                                                target="_blank"
                                                rel="noopener noreferrer"
                                                >{{ obj }}</a
                                            >
                                        }
                                        @case ('object') {
                                            [<span
                                                class="hover:text-info font-mono underline"
                                                customTooltip
                                                xPosition="center"
                                                yPosition="bottom"
                                                [content]="json_tooltip"
                                                [data]="obj"
                                                [hover]="true"
                                                [backdrop]="false"
                                                >Object</span
                                            >]
                                        }
                                        @default {
                                            {{ obj }}
                                        }
                                    }
                                </div>
                            }
                        </div>
                        <div class="h-8 w-full"></div>
                    </cdk-virtual-scroll-viewport>
                } @else {
                    <div
                        class="flex h-120 w-full flex-1 flex-col items-center justify-center"
                    >
                        <div class="text-2xl opacity-30">
                            No {{ filter() ? 'matching' : '' }} logs
                        </div>
                    </div>
                }
                <div
                    class="absolute right-1 bottom-1 flex w-[20rem] items-center overflow-hidden rounded-lg p-1"
                >
                    <div
                        class="bg-base-content absolute inset-0 z-0 opacity-60"
                    ></div>
                    <div
                        class="bg-base-content absolute inset-1 z-0 rounded-sm opacity-90"
                    ></div>
                    <input
                        #search_input
                        name="log-filter"
                        [ngModel]="filter()"
                        (ngModelChange)="filter.set($event)"
                        placeholder="Filter logs..."
                        class="text-base-100 relative flex-1 rounded-sm border-none px-2 py-1 font-mono text-sm"
                    />
                    <div
                        class="text-base-100 relative px-2 text-center font-mono text-xs"
                    >
                        @if (filter()?.length) {
                            <span class="font-mono">
                                {{ filtered_logs()?.length || '0' }} of
                            </span>
                        }
                        {{ logs()?.length }}
                    </div>
                </div>
            </div>
        }
        @if (can_activate) {
            <button
                activation
                class="absolute right-0 bottom-0 h-12 w-12"
                (mousedown)="onStart()"
                (touchstart)="onStart()"
                (mouseup)="onEnd()"
                (touchend)="onEnd()"
            ></button>
        }
    `,
    styles: [``],
    imports: [
        ScrollingModule,
        MatRippleModule,
        FormsModule,
        DatePipe,
        TranslatePipe,
        IconComponent,
        CustomTooltipComponent,
    ],
})
export class DebugConsoleComponent extends AsyncHandler implements OnInit {
    private _org = inject(OrganisationService);
    private _logs = inject(RemoteLoggingService);
    private _hotkey = inject(HotkeysService);
    private _settings = inject(SettingsService);

    public readonly show = model(false);
    public readonly hotkeysEnabled = input(true);
    public readonly colors = COLOR_MAP;
    public readonly json_tooltip = JsonDisplayComponent;
    public readonly filter = signal<string>('');
    public readonly logs = signal<ClientEvent[]>([]);
    /** Logs that match the filter. While the filter stays the same, only new logs are searched. */
    public readonly filtered_logs = linkedSignal<
        { filter: string; logs: ClientEvent[] },
        ClientEvent[]
    >({
        source: () => ({
            filter: this.filter().toLowerCase(),
            logs: this.logs(),
        }),
        computation: ({ filter, logs }, previous) => {
            if (!filter) return logs;
            const search = (list: ClientEvent[]) =>
                list.filter((_) => logSearchText(_).includes(filter));
            if (previous?.source.filter !== filter) return search(logs);
            // The history only adds logs at the end and drops them at the start
            const old_logs = previous.source.logs;
            const end = logs.lastIndexOf(old_logs[old_logs.length - 1]);
            const dropped = old_logs.length - 1 - end;
            if (end < 0 || logs[0] !== old_logs[dropped]) return search(logs);
            const matches = previous.value;
            let start = 0;
            for (let i = 0; i < dropped && start < matches.length; i++) {
                if (matches[start] === old_logs[i]) start++;
            }
            return [...matches.slice(start), ...search(logs.slice(end + 1))];
        },
    });

    public readonly onStart = () =>
        this.timeout('show', () => this.show.set(true), 5000);
    public readonly onEnd = () => this.clearTimeout('show');
    private readonly _can_activate = this._settings.signal(
        'debug_console',
        false,
    );
    private readonly _log_limits = this._settings.signal('log_limits', 20000);

    public get can_activate() {
        return this._can_activate();
    }

    constructor() {
        super();
        effect(() => {
            if (!this._org.initialised()) return;
            this._org.active_building();
            const binding = this._org.binding('remote_logger');
            const system_id = binding instanceof Object ? binding.id : binding;
            this._logs.setSystem(system_id);
        });
        effect(() => {
            const log_list = this._logs.history();
            const limit = this._log_limits();
            this.logs.set(
                log_list.length > limit ? log_list.slice(-limit) : log_list,
            );
        });
    }

    public ngOnInit() {
        if (!this.hotkeysEnabled()) return;
        this.subscription(
            'toggle',
            this._hotkey.listen(['Control', 'Backquote'], () =>
                this.show.set(!this.show()),
            ),
        );
    }

    public type(item: unknown) {
        if (
            typeof item === 'string' &&
            URL_STARTS.find((start) => item.startsWith(start))
        ) {
            return 'link';
        } else if (item instanceof Object) {
            return 'object';
        }
        return 'string';
    }

    /** Track logs by ID. Many logs can share the same timestamp. */
    public trackByFn(_: number, item: ClientEvent) {
        return item?.id;
    }
}
